# Draws AstroHybrid's own icon - no game artwork is used anywhere in the public app.
#
# The mark (violet badge, white sparkle, amber orbit) is generated by
# Tools/brand/make_logo.py, which needs Python and Pillow. This script is the
# PowerShell equivalent for people who just want to regenerate the icon on a
# Windows box without Python.
#
#   powershell -ExecutionPolicy Bypass -File Tools\release\make_icon.ps1
#
# It writes AstroHybrid.App\Resources\astrohybrid.png (512 px) and astrohybrid.ico.
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Drawing.Common -ErrorAction SilentlyContinue
$root = Split-Path (Split-Path $PSScriptRoot -Parent) -Parent
$out = Join-Path $root 'AstroHybrid.App\Resources'

function Gradient-Badge([int]$n) {
    $bmp = New-Object Drawing.Bitmap $n, $n
    $g = [Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = 'AntiAlias'
    $g.PixelOffsetMode = 'HighQuality'
    $g.Clear([Drawing.Color]::Transparent)

    $inset = [Math]::Round($n * 0.045)
    $r = [Math]::Round($n * 0.225)
    $w = $n - 2 * $inset - 1
    $path = New-Object Drawing.Drawing2D.GraphicsPath
    $path.AddArc($inset, $inset, 2 * $r, 2 * $r, 180, 90)
    $path.AddArc($inset + $w - 2 * $r, $inset, 2 * $r, 2 * $r, 270, 90)
    $path.AddArc($inset + $w - 2 * $r, $inset + $w - 2 * $r, 2 * $r, 2 * $r, 0, 90)
    $path.AddArc($inset, $inset + $w - 2 * $r, 2 * $r, 2 * $r, 90, 90)
    $path.CloseFigure()

    $rect = New-Object Drawing.Rectangle $inset, $inset, $w, $w
    $brush = New-Object Drawing.Drawing2D.LinearGradientBrush(
        $rect,
        [Drawing.Color]::FromArgb(255, 124, 106, 255),
        [Drawing.Color]::FromArgb(255, 58, 34, 168),
        [Drawing.Drawing2D.LinearGradientMode]::Vertical)
    $g.FillPath($brush, $path)

    # Four-point sparkle (concave sides).
    $cx = $n / 2.0
    $cy = $n * 0.49
    $rx = $n * 0.315
    $ry = $n * 0.295
    $waist = 0.42
    $pts = New-Object 'Drawing.PointF[]' 8
    for ($i = 0; $i -lt 8; $i++) {
        $angle = -[Math]::PI / 2 + $i * [Math]::PI / 4
        $k = if ($i % 2 -eq 0) { 1.0 } else { $waist }
        $pts[$i] = New-Object Drawing.PointF ([float]($cx + $k * $rx * [Math]::Cos($angle))), ([float]($cy + $k * $ry * [Math]::Sin($angle)))
    }
    $g.FillPolygon([Drawing.Brushes]::White, $pts)

    # Smaller companion sparkle, upper right.
    $mx = $n * 0.755
    $my = $n * 0.275
    $mr = $n * 0.094
    $mp = New-Object 'Drawing.PointF[]' 8
    for ($i = 0; $i -lt 8; $i++) {
        $angle = -[Math]::PI / 2 + $i * [Math]::PI / 4
        $k = if ($i % 2 -eq 0) { 1.0 } else { 0.38 }
        $mp[$i] = New-Object Drawing.PointF ([float]($mx + $k * $mr * [Math]::Cos($angle))), ([float]($my + $k * $mr * 0.94 * [Math]::Sin($angle)))
    }
    $g.FillPolygon([Drawing.Brushes]::White, $mp)

    # Amber orbit ring around the sparkle.
    $ringPen = New-Object Drawing.Pen ([Drawing.Color]::FromArgb(200, 255, 196, 92)), ([float]($n * 0.014))
    $ringRect = New-Object Drawing.RectangleF ([float]($cx - $n * 0.315)), ([float]($cy - $n * 0.195)), ([float]($n * 0.63)), ([float]($n * 0.39))
    $g.DrawEllipse($ringPen, $ringRect)
    $ringPen.Dispose()
    $brush.Dispose()
    $g.Dispose()
    return $bmp
}

function Png-Bytes($bmp) {
    $ms = New-Object IO.MemoryStream
    $bmp.Save($ms, [Drawing.Imaging.ImageFormat]::Png)
    return ,$ms.ToArray()
}

# 512 px master (the UI uses this at 34 px in the sidebar and 120 px on Home).
$master = Gradient-Badge 1024
$png512 = New-Object Drawing.Bitmap $master, 512, 512
$png512.Save((Join-Path $out 'astrohybrid.png'), [Drawing.Imaging.ImageFormat]::Png)

# ICO with PNG-compressed frames, built by hand so Windows 10/11 picks the right size.
$sizes = @(16, 24, 32, 48, 64, 128, 256)
$frames = @()
foreach ($s in $sizes) {
    $b = New-Object Drawing.Bitmap $master, $s, $s
    $frames += ,(Png-Bytes $b)
    $b.Dispose()
}

$ico = New-Object IO.MemoryStream
$bw = New-Object IO.BinaryWriter $ico
$bw.Write([UInt16]0)                  # reserved
$bw.Write([UInt16]1)                  # type: icon
$bw.Write([UInt16]$sizes.Count)       # image count
$offset = 6 + 16 * $sizes.Count
for ($i = 0; $i -lt $sizes.Count; $i++) {
    $dim = if ($sizes[$i] -ge 256) { 0 } else { $sizes[$i] }
    $bw.Write([Byte]$dim)             # width
    $bw.Write([Byte]$dim)             # height
    $bw.Write([Byte]0)                # palette
    $bw.Write([Byte]0)                # reserved
    $bw.Write([UInt16]1)              # colour planes
    $bw.Write([UInt16]32)             # bits per pixel
    $bw.Write([UInt32]$frames[$i].Length)
    $bw.Write([UInt32]$offset)
    $offset += $frames[$i].Length
}
foreach ($f in $frames) { $bw.Write($f) }
[IO.File]::WriteAllBytes((Join-Path $out 'astrohybrid.ico'), $ico.ToArray())
$bw.Dispose()

$master.Dispose()
$png512.Dispose()
Write-Host "Wrote astrohybrid.png and astrohybrid.ico to $out"
